export type AppConfig = {
  port: number;
  host: string;
  logLevel: string;
  /** When false, /ready returns not ready (for drain / dependency checks). */
  ready: boolean;
};

export function loadConfig(env: NodeJS.ProcessEnv = process.env): AppConfig {
  const port = Number(env.PORT ?? "8080");
  const host = env.HOST ?? "0.0.0.0";
  const logLevel = env.LOG_LEVEL ?? "info";
  const ready = env.READY !== "false";

  if (Number.isNaN(port) || port <= 0) {
    throw new Error("PORT must be a positive number");
  }

  return { port, host, logLevel, ready };
}

import pino from "pino";
import type { AppConfig } from "../config.js";

export function createLogger(config: AppConfig) {
  return pino({
    level: config.logLevel,
    base: { service: "agentic-sdlc-service" },
    timestamp: pino.stdTimeFunctions.isoTime,
  });
}

export type Logger = ReturnType<typeof createLogger>;

import {
  Registry,
  collectDefaultMetrics,
  Counter,
  Histogram,
} from "prom-client";

export function createMetricsRegistry() {
  const register = new Registry();
  collectDefaultMetrics({ register });

  const httpRequestsTotal = new Counter({
    name: "http_requests_total",
    help: "Total HTTP requests",
    labelNames: ["method", "route", "status_code"],
    registers: [register],
  });

  const httpRequestDurationSeconds = new Histogram({
    name: "http_request_duration_seconds",
    help: "HTTP request duration in seconds",
    labelNames: ["method", "route", "status_code"],
    buckets: [0.005, 0.01, 0.025, 0.05, 0.1, 0.25, 0.5, 1, 2.5, 5],
    registers: [register],
  });

  return { register, httpRequestsTotal, httpRequestDurationSeconds };
}

export type Metrics = ReturnType<typeof createMetricsRegistry>;

import type { Logger } from "./logger.js";

/**
 * Placeholder for OpenTelemetry wiring.
 * Point `OTEL_EXPORTER_OTLP_ENDPOINT` at your collector and add `@opentelemetry/sdk-node`
 * when you want distributed traces; until then we propagate request IDs in logs only.
 */
export type TraceContext = {
  traceId: string;
};

export function parseOrCreateTraceContext(
  headers: Record<string, string | string[] | undefined>,
  logger: Logger,
): TraceContext {
  const traceparent = headers["traceparent"];
  const raw = Array.isArray(traceparent) ? traceparent[0] : traceparent;
  if (typeof raw === "string" && raw.length >= 18) {
    const traceId = raw.slice(3, 35);
    if (/^[0-9a-f]{32}$/i.test(traceId)) {
      return { traceId };
    }
  }
  const traceId = crypto.randomUUID().replace(/-/g, "");
  logger.debug({ traceId }, "generated trace id");
  return { traceId };
}

import Fastify from "fastify";
import type { AppConfig } from "./config.js";
import type { Logger } from "./observability/logger.js";
import type { Metrics } from "./observability/metrics.js";
import { parseOrCreateTraceContext } from "./observability/tracing.js";

export function buildApp(config: AppConfig, logger: Logger, metrics: Metrics) {
  const app = Fastify({
    loggerInstance: logger,
    disableRequestLogging: false,
    genReqId: () => crypto.randomUUID(),
  });

  app.addHook("onRequest", async (req) => {
    const tc = parseOrCreateTraceContext(req.headers as Record<string, unknown>, logger);
    req.log = req.log.child({ traceId: tc.traceId });
  });

  app.addHook("onResponse", async (req, reply) => {
    const route = req.routeOptions?.url ?? req.url.split("?")[0] ?? "unknown";
    const labels = {
      method: req.method,
      route,
      status_code: String(reply.statusCode),
    };
    metrics.httpRequestsTotal.inc(labels);
    metrics.httpRequestDurationSeconds.observe(
      labels,
      reply.elapsedTime / 1000,
    );
  });

  app.get("/health", async () => ({
    status: "ok",
    uptimeSeconds: Math.round(process.uptime()),
  }));

  app.get("/ready", async (_req, reply) => {
    if (!config.ready) {
      return reply.code(503).send({ status: "not_ready" });
    }
    return { status: "ready" };
  });

  app.get("/metrics", async (_req, reply) => {
    reply.header("content-type", metrics.register.contentType);
    return reply.send(await metrics.register.metrics());
  });

  return app;
}

import { loadConfig } from "./config.js";
import { buildApp } from "./app.js";
import { createLogger } from "./observability/logger.js";
import { createMetricsRegistry } from "./observability/metrics.js";

const config = loadConfig();
const logger = createLogger(config);
const metrics = createMetricsRegistry();
const app = buildApp(config, logger, metrics);

try {
  await app.listen({ port: config.port, host: config.host });
  logger.info({ port: config.port, host: config.host }, "server listening");
} catch (err) {
  logger.error({ err }, "failed to start server");
  process.exit(1);
}

const shutdown = async (signal: string) => {
  logger.info({ signal }, "shutdown requested");
  await app.close();
  process.exit(0);
};

process.on("SIGINT", () => void shutdown("SIGINT"));
process.on("SIGTERM", () => void shutdown("SIGTERM"));

